/*Table structure for table `c_faqs` */

DROP TABLE IF EXISTS `c_faqs`;

CREATE TABLE `c_faqs` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `question_en` varchar(500) NOT NULL,
  `question_id` varchar(500) DEFAULT NULL,
  `question_ms` varchar(500) DEFAULT NULL,
  `answer_en` text NOT NULL,
  `answer_id` text DEFAULT NULL,
  `answer_ms` text DEFAULT NULL,
  `status` enum('draft','published','deleted') NOT NULL DEFAULT 'draft',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=16 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

/*Data for the table `c_faqs` */

insert  into `c_faqs`(`id`,`question_en`,`question_id`,`question_ms`,`answer_en`,`answer_id`,`answer_ms`,`status`,`created_at`,`updated_at`,`deleted_at`) values (1,'How do I book a vehicle?','Bagaimana cara memesan kendaraan?','Bagaimana cara menempah kenderaan?','Choose a vehicle in Our Fleet and tap \"Book via WhatsApp\". Send us your travel date, pickup point, destination and number of passengers. We will confirm availability and send you the price before you confirm the booking.','Pilih kendaraan di bagian Armada Kami, lalu tekan \"Pesan via WhatsApp\". Kirimkan tanggal perjalanan, lokasi penjemputan, tujuan, dan jumlah penumpang. Kami akan mengonfirmasi ketersediaan dan mengirimkan harga sebelum Anda memastikan pesanan.','Pilih kenderaan di bahagian Armada Kami, kemudian tekan \"Tempah melalui WhatsApp\". Hantar tarikh perjalanan, lokasi ambilan, destinasi dan bilangan penumpang. Kami akan mengesahkan ketersediaan dan menghantar harga sebelum anda mengesahkan tempahan.','published','2026-11-15 01:32:47','2026-11-15 01:32:47',NULL),(2,'Which vehicle is right for my group?','Kendaraan apa yang cocok untuk rombongan saya?','Kenderaan mana yang sesuai untuk kumpulan saya?','Toyota Avanza and Kijang Innova Reborn are 7-seat MPVs for families and small groups. Toyota Alphard is our premium MPV for VIP guests and special occasions. Toyota Hiace carries up to 14 passengers, and our medium bus seats 25 to 35 people for large groups. Tell us how many people and how much luggage you have, and we will suggest the best fit.','Toyota Avanza dan Kijang Innova Reborn adalah MPV 7 kursi untuk keluarga dan grup kecil. Toyota Alphard adalah MPV premium untuk tamu VIP dan acara spesial. Toyota Hiace memuat hingga 14 penumpang, dan bus medium kami berkapasitas 25 sampai 35 kursi untuk rombongan besar. Beri tahu kami jumlah penumpang dan bagasi, kami bantu pilihkan yang paling pas.','Toyota Avanza dan Kijang Innova Reborn ialah MPV 7 tempat duduk untuk keluarga dan kumpulan kecil. Toyota Alphard ialah MPV premium kami untuk tetamu VIP dan acara istimewa. Toyota Hiace memuatkan sehingga 14 penumpang, dan bas sederhana kami mempunyai 25 hingga 35 tempat duduk untuk kumpulan besar. Beritahu kami bilangan penumpang dan bagasi, dan kami akan cadangkan pilihan terbaik.','published','2026-11-15 01:32:47','2026-11-15 01:32:47',NULL),(3,'Does the rental include a driver?','Apakah sewa sudah termasuk sopir?','Adakah sewaan termasuk pemandu?','Yes. Our vehicles come with a friendly driver who knows the roads in Batam, so you can relax and enjoy the trip without worrying about directions or parking.','Ya. Kendaraan kami dikemudikan oleh sopir ramah yang mengenal jalanan Batam, sehingga Anda bisa bersantai menikmati perjalanan tanpa memikirkan rute atau parkir.','Ya. Kenderaan kami dipandu oleh pemandu yang mesra dan mengenali jalan di Batam, jadi anda boleh berehat dan menikmati perjalanan tanpa risau tentang laluan atau tempat letak kereta.','published','2026-11-15 01:32:47','2026-11-15 01:32:47',NULL),(4,'Can you pick me up at the airport or a ferry terminal?','Apakah bisa dijemput di bandara atau pelabuhan feri?','Bolehkah saya diambil di lapangan terbang atau terminal feri?','Yes. We provide transfers from Hang Nadim International Airport and from Batam ferry terminals such as Batam Centre, Harbour Bay, Sekupang and Nongsa Pura. Send us your flight or ferry details and arrival time so the driver can be there when you arrive.','Ya. Kami melayani antar-jemput dari Bandara Internasional Hang Nadim dan pelabuhan feri di Batam seperti Batam Centre, Harbour Bay, Sekupang, dan Nongsa Pura. Kirimkan detail penerbangan atau feri serta jam kedatangan agar sopir sudah siap saat Anda tiba.','Ya. Kami menyediakan pengangkutan dari Lapangan Terbang Antarabangsa Hang Nadim dan terminal feri di Batam seperti Batam Centre, Harbour Bay, Sekupang dan Nongsa Pura. Hantar butiran penerbangan atau feri serta masa ketibaan supaya pemandu sudah bersedia apabila anda tiba.','published','2026-11-15 01:32:47','2026-11-15 01:32:47',NULL),(5,'Can you arrange a city tour or an island trip?','Apakah bisa diatur city tour atau wisata ke pulau?','Bolehkah anda uruskan lawatan bandar atau perjalanan ke pulau?','Yes. Popular stops include Barelang Bridge, Galang and Rempang, Maha Vihara Duta Maitreya and Nongsa. Tell us which places you want to visit and how much time you have, and we will help plan the route. See News & Information for destination ideas.','Bisa. Tujuan favorit antara lain Jembatan Barelang, Galang dan Rempang, Maha Vihara Duta Maitreya, serta Nongsa. Beri tahu kami tempat yang ingin dikunjungi dan waktu yang tersedia, kami bantu atur rutenya. Lihat Berita & Informasi untuk ide destinasi.','Boleh. Antara destinasi popular ialah Jambatan Barelang, Galang dan Rempang, Maha Vihara Duta Maitreya serta Nongsa. Beritahu kami tempat yang ingin dilawati dan masa yang ada, dan kami akan bantu merancang laluan. Lihat Berita & Maklumat untuk idea destinasi.','published','2026-11-15 01:32:47','2026-11-15 01:32:47',NULL),(6,'How is the price calculated?','Bagaimana harga sewa dihitung?','Bagaimana harga sewaan dikira?','The price depends on the vehicle, the rental duration and your route. We send you a complete quote on WhatsApp, including what it covers, before you confirm, so there are no surprises.','Harga tergantung pada jenis kendaraan, lama sewa, dan rute perjalanan. Kami mengirimkan penawaran lengkap lewat WhatsApp, termasuk apa saja yang sudah tercakup, sebelum Anda memastikan pesanan.','Harga bergantung pada jenis kenderaan, tempoh sewaan dan laluan perjalanan. Kami akan menghantar sebut harga lengkap melalui WhatsApp, termasuk perkara yang diliputi, sebelum anda mengesahkan tempahan.','published','2026-11-15 01:32:47','2026-11-15 01:32:47',NULL),(7,'How far in advance should I book?','Berapa lama sebelumnya saya sebaiknya memesan?','Berapa awal saya patut membuat tempahan?','Book as early as you can, especially for weekends, public and school holidays, and for the Alphard, Hiace or bus. For last-minute trips, message us anyway and we will check what is available.','Sebaiknya pesan sedini mungkin, terutama untuk akhir pekan, libur nasional dan libur sekolah, serta untuk Alphard, Hiace, atau bus. Untuk perjalanan mendadak, tetap hubungi kami dan kami cek ketersediaannya.','Tempah seawal mungkin, terutamanya untuk hujung minggu, cuti umum dan cuti sekolah, serta untuk Alphard, Hiace atau bas. Untuk perjalanan saat akhir, hubungi kami juga dan kami akan semak ketersediaan.','published','2026-11-15 01:32:47','2026-11-15 01:32:47',NULL),(8,'Can I change or cancel my booking?','Apakah pesanan bisa diubah atau dibatalkan?','Bolehkah saya menukar atau membatalkan tempahan?','Message us on WhatsApp as soon as your plans change. We will do our best to adjust the date, time or vehicle. The change and cancellation terms for your booking are explained when you book.','Hubungi kami lewat WhatsApp segera setelah rencana Anda berubah. Kami akan berusaha menyesuaikan tanggal, jam, atau kendaraan. Ketentuan perubahan dan pembatalan untuk pesanan Anda dijelaskan saat pemesanan.','Hubungi kami melalui WhatsApp sebaik sahaja rancangan anda berubah. Kami akan cuba sedaya upaya untuk menyesuaikan tarikh, masa atau kenderaan. Syarat perubahan dan pembatalan untuk tempahan anda dijelaskan semasa tempahan dibuat.','published','2026-11-15 01:32:47','2026-11-15 01:32:47',NULL);

/*Table structure for table `c_fleet` */

DROP TABLE IF EXISTS `c_fleet`;

CREATE TABLE `c_fleet` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `name_en` varchar(200) NOT NULL,
  `name_id` varchar(200) DEFAULT NULL,
  `name_ms` varchar(200) DEFAULT NULL,
  `description_en` text DEFAULT NULL,
  `description_id` text DEFAULT NULL,
  `description_ms` text DEFAULT NULL,
  `image_path` varchar(500) DEFAULT NULL,
  `status` enum('draft','published','deleted') NOT NULL DEFAULT 'draft',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=9 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

/*Data for the table `c_fleet` */

insert  into `c_fleet`(`id`,`name_en`,`name_id`,`name_ms`,`description_en`,`description_id`,`description_ms`,`image_path`,`status`,`created_at`,`updated_at`,`deleted_at`) values (1,'Toyota Avanza','Toyota Avanza','Toyota Avanza','7-seat MPV that is fuel-efficient and comfortable, ideal for families and small groups. Air-conditioned and perfect for city trips and airport transfers.','MPV 7 kursi yang irit dan nyaman, cocok untuk keluarga dan grup kecil. Ber-AC dan pas untuk keliling kota maupun antar-jemput bandara.','MPV 7 tempat duduk yang jimat dan selesa, sesuai untuk keluarga dan kumpulan kecil. Berhawa dingin dan sesuai untuk lawatan bandar serta pengangkutan lapangan terbang.','uploads/fleet/bbff4dd059334abf852ebf58e5f16ba6.png','published','2026-11-14 22:06:54','2026-11-14 15:22:57',NULL),(2,'Toyota Kijang Innova Reborn','Toyota Kijang Innova Reborn','Toyota Kijang Innova Reborn','Spacious 7-seat MPV with a smooth ride and generous legroom. A reliable choice for longer trips, island tours and business travel.','MPV 7 kursi yang lega dengan kenyamanan berkendara terbaik di kelasnya. Pilihan andal untuk perjalanan jauh, tur pulau, dan perjalanan bisnis.','MPV 7 tempat duduk yang luas dengan perjalanan yang lancar dan ruang kaki selesa. Pilihan boleh dipercayai untuk perjalanan jauh, lawatan pulau dan perjalanan perniagaan.','uploads/fleet/d8ef40868903b02b189599d67ef726b9.png','published','2026-11-14 22:06:54','2026-11-14 15:23:20',NULL),(3,'Toyota Alphard (Premium)','Toyota Alphard (Premium)','Toyota Alphard (Premium)','Premium MPV with plush captain seats and a quiet cabin. Ideal for VIP guests, executive transfers, weddings and special occasions.','MPV premium dengan kursi captain empuk dan kabin senyap. Cocok untuk tamu VIP, antar-jemput eksekutif, pernikahan, dan acara spesial.','MPV premium dengan tempat duduk kapten yang empuk dan kabin senyap. Sesuai untuk tetamu VIP, pengangkutan eksekutif, majlis perkahwinan dan acara istimewa.','uploads/fleet/fd7b2b9c380f0de49c53f16e008d4439.png','published','2026-11-14 22:06:54','2026-11-14 15:23:36',NULL),(4,'Toyota Hiace Commuter','Toyota Hiace Commuter','Toyota Hiace Commuter','Spacious van for up to 14 passengers with strong air-conditioning and ample luggage space. Great for group tours, family gatherings and airport transfers.','Van lega untuk hingga 14 penumpang dengan AC dingin dan bagasi luas. Pas untuk tur rombongan, acara keluarga, dan antar-jemput bandara.','Van luas untuk sehingga 14 penumpang dengan penghawa dingin yang kuat dan ruang bagasi yang besar. Sesuai untuk lawatan berkumpulan, perhimpunan keluarga dan pengangkutan lapangan terbang.','uploads/fleet/816516ec32fb2e364e26185852c47f82.png','published','2026-11-14 22:06:54','2026-11-14 15:23:48',NULL),(5,'Medium Bus (25–35 Seats)','Bus Medium (25–35 Kursi)','Bas Sederhana (25–35 Tempat Duduk)','Comfortable air-conditioned bus for large groups such as company outings, school trips and tour groups. Reclining seats with space for luggage.','Bus ber-AC yang nyaman untuk rombongan besar seperti gathering kantor, study tour, dan wisata grup. Kursi reclining dengan bagasi luas.','Bas berhawa dingin yang selesa untuk kumpulan besar seperti lawatan syarikat, lawatan sekolah dan kumpulan pelancong. Tempat duduk boleh sandar dengan ruang bagasi.','uploads/fleet/3c36d4e51014db40c1080c5e4be97816.png','published','2026-11-14 22:06:54','2026-11-14 15:24:02',NULL),(8,'Daihatsu Xenia','Daihatsu Xenia','Daihatsu Xenia','Tes english','tes indonesia','tes melayu','uploads/fleet/f1edabbac330e90e67bcd19eb7b731df.png','deleted','2026-11-15 11:44:38','2026-11-15 11:45:23','2026-11-15 11:45:23');

/*Table structure for table `c_gallery` */

