insert  into `c_gallery`(`id`,`caption_en`,`caption_id`,`caption_ms`,`image_path`,`sort_order`,`status`,`created_at`,`updated_at`,`deleted_at`) values (1,'Coastal road trip in a white Toyota','Perjalanan menyusuri pantai dengan Toyota putih','Perjalanan di tepi pantai dengan Toyota putih','uploads/gallery/coastal-road-trip-white-toyota.png',1,'published','2026-11-14 23:26:27','2026-11-14 23:26:27',NULL),(2,'Mountain roadside adventure with a Toyota SUV','Petualangan di jalur pegunungan dengan SUV Toyota','Pengembaraan di tepi jalan pergunungan dengan SUV Toyota','uploads/gallery/mountain-roadside-toyota-suv.png',2,'published','2026-11-14 23:26:27','2026-11-14 23:26:27',NULL),(3,'Arriving at a tropical resort in a luxury MPV','Tiba di resor tropis dengan MPV mewah','Tiba di resort tropika dengan MPV mewah','uploads/gallery/tropical-resort-arrival-luxury-mpv.png',3,'published','2026-11-14 23:26:27','2026-11-14 23:26:27',NULL),(4,'Silver van at a modern city plaza','Van perak di plaza kota modern','Van perak di plaza bandar moden','uploads/gallery/silver-van-modern-city-plaza.png',4,'published','2026-11-14 23:26:27','2026-11-14 23:26:27',NULL),(5,'Smiling tourists by the mountain lake','Wisatawan tersenyum di tepi danau pegunungan','Pelancong tersenyum di tepi tasik pergunungan','uploads/gallery/smiling-tourists-mountain-lake.png',5,'published','2026-11-14 23:26:27','2026-11-14 23:26:27',NULL),(6,'Golden-hour coastal road trip','Perjalanan pantai saat golden hour','Perjalanan tepi pantai ketika golden hour','uploads/gallery/golden-hour-coastal-road-trip.png',6,'published','2026-11-14 23:26:27','2026-11-14 23:26:27',NULL);

