/*Data for the table `c_news` */

insert  into `c_news`(`id`,`title_en`,`title_id`,`title_ms`,`body_en`,`body_id`,`body_ms`,`image_path`,`publish_date`,`status`,`created_at`,`updated_at`,`deleted_at`) values (3,'Barelang Bridge: Batam Iconic Road Trip','Jembatan Barelang: Ikon Wisata Road Trip Batam','Jambatan Barelang: Ikon Perjalanan Darat Batam','Barelang Bridge is a chain of six bridges, built in 1997, that links Batam with Rempang and Galang islands. The name Barelang comes from the three islands it connects: BAtam, REmpang and GAlang.\r\n\r\nThe bridges lie roughly 35 km from Batam city, so the drive itself is part of the fun, with sea views and island scenery along the way. Each span looks different, and the cable-stayed ones make the best photo stops.\r\n\r\nTip: travel in the morning or late afternoon to avoid the midday heat, and bring water. A rental car or van with a driver lets you stop wherever you like.','Jembatan Barelang adalah rangkaian enam jembatan yang dibangun pada 1997 untuk menghubungkan Pulau Batam dengan Pulau Rempang dan Galang. Nama Barelang berasal dari tiga pulau yang dihubungkannya: BAtam, REmpang, dan GAlang.\r\n\r\nJembatan ini berjarak sekitar 35 km dari pusat Kota Batam, sehingga perjalanannya sendiri sudah menjadi bagian dari wisata, dengan pemandangan laut dan pulau di sepanjang jalan. Setiap bentang jembatan punya bentuk berbeda, dan jembatan kabel menjadi spot foto favorit.\r\n\r\nTips: berangkat pagi atau sore hari agar tidak terlalu panas, dan bawa air minum. Dengan mobil atau van sewaan beserta sopir, Anda bebas berhenti di titik mana pun.','Jambatan Barelang ialah rangkaian enam jambatan yang dibina pada 1997 untuk menghubungkan Pulau Batam dengan Pulau Rempang dan Galang. Nama Barelang datang daripada tiga pulau yang dihubungkannya: BAtam, REmpang dan GAlang.\r\n\r\nJambatan ini terletak kira-kira 35 km dari pusat bandar Batam, jadi perjalanannya sendiri sudah menjadi sebahagian daripada pengalaman, dengan pemandangan laut dan pulau sepanjang jalan. Setiap rentang jambatan berbeza bentuknya, dan jambatan kabel menjadi tempat bergambar yang digemari.\r\n\r\nPetua: bertolak pada waktu pagi atau lewat petang supaya tidak terlalu panas, dan bawa air minuman. Dengan kereta atau van sewa berserta pemandu, anda boleh berhenti di mana-mana sahaja.','uploads/news/a137244098bcd77d0387bbe163523fb1.png','2026-11-15 00:49:00','published','2026-11-15 00:49:04','2026-11-14 17:52:09',NULL),(4,'Galang and Rempang: History and Coastal Village Life','Galang dan Rempang: Sejarah dan Kehidupan Kampung Pesisir','Galang dan Rempang: Sejarah dan Kehidupan Kampung Pesisir','South of Batam, Galang and Rempang islands offer a quieter side of the Riau Islands. Galang is known for its former Vietnamese refugee camp, a historic site that many visitors combine with a trip across the Barelang bridges.\r\n\r\nRempang is a rural island dotted with coastal villages built on stilts over the water, a good place to see everyday island life and try local dishes.\r\n\r\nBoth islands are easy to reach by road from Batam. Plan a full day, and ask us about a driver who knows the route.','Di selatan Batam, Pulau Galang dan Rempang menawarkan sisi Kepulauan Riau yang lebih tenang. Galang dikenal karena bekas kamp pengungsi Vietnam, situs bersejarah yang sering dikunjungi sekaligus dalam perjalanan melintasi jembatan Barelang.\r\n\r\nRempang adalah pulau pedesaan dengan kampung-kampung pesisir berumah panggung di atas air, tempat yang pas untuk melihat keseharian warga pulau dan mencicipi hidangan lokal.\r\n\r\nKedua pulau mudah dijangkau lewat jalan darat dari Batam. Sediakan waktu satu hari penuh, dan tanyakan kepada kami soal sopir yang mengenal rutenya.','Di selatan Batam, Pulau Galang dan Rempang menawarkan sisi Kepulauan Riau yang lebih tenang. Galang terkenal dengan bekas kem pelarian Vietnam, tapak bersejarah yang sering dikunjungi sekali gus dalam perjalanan merentasi jambatan Barelang.\r\n\r\nRempang ialah pulau luar bandar dengan kampung-kampung pesisir berumah panggung di atas air, tempat yang sesuai untuk melihat kehidupan harian penduduk pulau dan mencuba hidangan tempatan.\r\n\r\nKedua-dua pulau mudah dihubungi melalui jalan darat dari Batam. Peruntukkan masa sehari penuh, dan tanyalah kami tentang pemandu yang mengenali laluannya.','uploads/news/a28a8eacb1a40b9f8df901ad793c4357.png','2026-11-14 00:49:00','published','2026-11-15 00:49:04','2026-11-15 00:58:37',NULL),(5,'Maha Vihara Duta Maitreya: A Peaceful Stop in Batam','Maha Vihara Duta Maitreya: Singgah Tenang di Batam','Maha Vihara Duta Maitreya: Persinggahan Tenang di Batam','Maha Vihara Duta Maitreya is one of the largest Buddhist temples in Southeast Asia. Its grounds cover about 4.5 hectares with five buildings, and the main hall, Graha Maitreya, can hold around 2,000 people.\r\n\r\nVisitors come for the calm gardens, the koi pond and the golden Maitreya Buddha statue, and it is a favourite stop on city tours.\r\n\r\nPlease dress modestly and respect the worshippers. It is a short drive from the city centre, so it fits easily into a half-day tour.','Maha Vihara Duta Maitreya adalah salah satu vihara terbesar di Asia Tenggara. Kompleksnya seluas sekitar 4,5 hektare dengan lima bangunan, dan aula utamanya, Graha Maitreya, dapat menampung sekitar 2.000 orang.\r\n\r\nPengunjung datang untuk menikmati taman yang asri, kolam ikan koi, dan patung Buddha Maitreya berlapis emas. Tempat ini menjadi persinggahan favorit dalam city tour.\r\n\r\nMohon berpakaian sopan dan hormati umat yang beribadah. Lokasinya hanya sejauh perjalanan singkat dari pusat kota, sehingga cocok untuk tur setengah hari.','Maha Vihara Duta Maitreya ialah salah sebuah vihara Buddha terbesar di Asia Tenggara. Kawasannya seluas kira-kira 4.5 hektar dengan lima bangunan, dan dewan utamanya, Graha Maitreya, boleh memuatkan kira-kira 2,000 orang.\r\n\r\nPengunjung datang untuk menikmati taman yang tenang, kolam ikan koi dan patung Buddha Maitreya bersalut emas. Tempat ini menjadi persinggahan kegemaran dalam lawatan bandar.\r\n\r\nSila berpakaian sopan dan hormati para penyembah. Lokasinya hanya perjalanan singkat dari pusat bandar, sesuai untuk lawatan separuh hari.','uploads/news/4174e97c0de33745a3584b8e812d4e83.png','2026-11-13 00:49:00','published','2026-11-15 00:49:04','2026-11-15 01:04:19',NULL),(6,'Nongsa Beach and Pulau Abang: Sea and Snorkelling','Pantai Nongsa dan Pulau Abang: Wisata Laut dan Snorkeling','Pantai Nongsa dan Pulau Abang: Pelancongan Laut dan Snorkeling','Nongsa, in the north-east of Batam, is a popular beach area. It is said to be named after Nong Isa, a ruler of the region in the 18th century.\r\n\r\nFor snorkelling and diving, Pulau Abang is one of the island destinations around Batam, reached by boat.\r\n\r\nPlan the transfer in advance: we can take you to the beach or the pier, and pick you up again when your trip ends.','Nongsa di timur laut Batam adalah kawasan pantai yang populer. Namanya dikatakan berasal dari Nong Isa, penguasa wilayah ini pada abad ke-18.\r\n\r\nUntuk snorkeling dan menyelam, Pulau Abang menjadi salah satu destinasi pulau di sekitar Batam yang dijangkau dengan perahu.\r\n\r\nRencanakan transportasi sejak awal: kami dapat mengantar Anda ke pantai atau dermaga, dan menjemput kembali saat perjalanan selesai.','Nongsa di timur laut Batam ialah kawasan pantai yang popular. Namanya dikatakan berasal daripada Nong Isa, pemerintah wilayah ini pada abad ke-18.\r\n\r\nUntuk snorkeling dan menyelam, Pulau Abang ialah salah satu destinasi pulau di sekitar Batam yang dihubungi dengan bot.\r\n\r\nRancang pengangkutan lebih awal: kami boleh menghantar anda ke pantai atau jeti, dan mengambil anda semula apabila perjalanan tamat.','uploads/news/ab148c2d520a2fdd1c6d51f972b4ae3a.png','2026-11-12 00:49:00','published','2026-11-15 00:49:04','2026-11-15 01:11:12',NULL),(7,'Foreign Visits to Batam Keep Rising','Kunjungan Wisatawan Mancanegara ke Batam Terus Naik','Kunjungan Pelancong Asing ke Batam Terus Meningkat','Batam continues to attract more international visitors. Statistics Indonesia (BPS) data, as reported in the media, shows 861,712 foreign tourist visits to Batam from January to July 2025, up 21.7% from the same period in 2024.\r\n\r\nFor the whole of 2024, foreign visits exceeded 1.16 million, compared with about 1.04 million the year before. In November 2024, Singapore alone made up about 52% of foreign visits, followed by Malaysia.\r\n\r\nMore visitors means busier weekends and holidays. If you plan a trip, we recommend booking your vehicle early so your preferred car, van or bus is available.','Batam terus menarik semakin banyak wisatawan mancanegara. Data Badan Pusat Statistik (BPS) yang diberitakan media mencatat 861.712 kunjungan wisatawan mancanegara ke Batam pada Januari-Juli 2025, naik 21,7% dibanding periode yang sama tahun 2024.\r\n\r\nSepanjang 2024, kunjungan wisatawan mancanegara melampaui 1,16 juta, dibanding sekitar 1,04 juta pada tahun sebelumnya. Pada November 2024, Singapura saja menyumbang sekitar 52% kunjungan, disusul Malaysia.\r\n\r\nPengunjung yang lebih banyak berarti akhir pekan dan musim libur lebih ramai. Jika Anda berencana datang, kami sarankan memesan kendaraan lebih awal agar mobil, van, atau bus pilihan Anda tersedia.','Batam terus menarik lebih ramai pelancong antarabangsa. Data Badan Pusat Statistik (BPS) yang dilaporkan media mencatatkan 861,712 kunjungan pelancong asing ke Batam pada Januari hingga Julai 2025, meningkat 21.7% berbanding tempoh yang sama pada 2024.\r\n\r\nSepanjang 2024, kunjungan pelancong asing melebihi 1.16 juta, berbanding kira-kira 1.04 juta pada tahun sebelumnya. Pada November 2024, Singapura sahaja menyumbang kira-kira 52% kunjungan, diikuti Malaysia.\r\n\r\nPengunjung yang lebih ramai bermakna hujung minggu dan musim cuti lebih sibuk. Jika anda merancang perjalanan, kami syorkan menempah kenderaan lebih awal supaya kereta, van atau bas pilihan anda tersedia.','uploads/news/8f220821cce2bb44ab49218d72c79640.png','2026-11-11 00:49:00','published','2026-11-15 00:49:04','2026-11-15 01:16:42',NULL),(8,'From Singapore to Batam: Ferry Terminals and Pickup Tips','Dari Singapura ke Batam: Pelabuhan Feri dan Tips Penjemputan','Dari Singapura ke Batam: Terminal Feri dan Petua Pengambilan','Batam is about 30 minutes by ferry from Singapore, which makes it an easy weekend trip. Ferries run from terminals such as HarbourFront and Tanah Merah in Singapore to Batam Center and Sekupang in Batam.\r\n\r\nBring your passport, and check the ferry schedule before you travel. Arrange your pickup in advance: tell us your arrival terminal and time, and a driver will be waiting.\r\n\r\nFrom the port we can take you straight to your hotel, to Barelang Bridge, or on a full city tour.','Batam hanya sekitar 30 menit dengan feri dari Singapura, sehingga mudah untuk liburan akhir pekan. Feri berangkat dari terminal seperti HarbourFront dan Tanah Merah di Singapura menuju Batam Center dan Sekupang di Batam.\r\n\r\nBawa paspor Anda dan cek jadwal feri sebelum berangkat. Atur penjemputan sejak awal: beri tahu kami terminal dan jam kedatangan, dan sopir akan menunggu Anda.\r\n\r\nDari pelabuhan, kami dapat mengantar Anda langsung ke hotel, ke Jembatan Barelang, atau untuk city tour sehari penuh.','Batam hanya kira-kira 30 minit dengan feri dari Singapura, jadi mudah untuk percutian hujung minggu. Feri bertolak dari terminal seperti HarbourFront dan Tanah Merah di Singapura menuju Batam Center dan Sekupang di Batam.\r\n\r\nBawa pasport anda dan semak jadual feri sebelum bertolak. Atur pengambilan lebih awal: beritahu kami terminal dan waktu ketibaan, dan pemandu akan menunggu anda.\r\n\r\nDari pelabuhan, kami boleh menghantar anda terus ke hotel, ke Jambatan Barelang, atau untuk lawatan bandar sehari penuh.','uploads/news/ba826f65ba6a7e46feefd54a41e5657f.png','2026-11-10 00:49:00','published','2026-11-15 00:49:04','2026-11-15 01:17:44',NULL);

/*Table structure for table `c_testimonials` */

DROP TABLE IF EXISTS `c_testimonials`;

CREATE TABLE `c_testimonials` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `customer_name` varchar(100) NOT NULL,
  `photo_path` varchar(500) DEFAULT NULL,
  `rating` tinyint(1) unsigned NOT NULL DEFAULT 5,
  `review_en` text NOT NULL,
  `review_id` text DEFAULT NULL,
  `review_ms` text DEFAULT NULL,
  `status` enum('draft','published','deleted') NOT NULL DEFAULT 'draft',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=13 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

/*Data for the table `c_testimonials` */

insert  into `c_testimonials`(`id`,`customer_name`,`photo_path`,`rating`,`review_en`,`review_id`,`review_ms`,`status`,`created_at`,`updated_at`,`deleted_at`) values (2,'Albert','uploads/testimonials/014b241386b233814be5ec36fd3ffa12.png',5,'Picked up right on time at Batam Centre ferry terminal. The driver was friendly and patient while our family group got ready. The car was clean and the air-conditioning was cold.','Dijemput tepat waktu di Pelabuhan Batam Centre. Sopirnya ramah dan sabar menunggu rombongan keluarga kami. Mobil bersih dan AC dingin.','Dijemput tepat pada masanya di Terminal Feri Batam Centre. Pemandunya mesra dan sabar menunggu rombongan keluarga kami. Kereta bersih dan penghawa dingin sejuk.','published','2026-11-15 05:52:10','2026-11-15 05:56:21',NULL),(3,'Jhon','uploads/testimonials/2ed1bf144c51a232f9c6b8d7a2ac6a94.png',5,'We rented a Hiace for 12 people to Barelang Bridge and Galang Island. The route was well planned and we could stop for photos at many spots. Recommended for groups.','Sewa Hiace untuk 12 orang ke Jembatan Barelang dan Pulau Galang. Rute diatur rapi, kami bisa berhenti foto di banyak spot. Recommended untuk rombongan.','Kami sewa Hiace untuk 12 orang ke Jambatan Barelang dan Pulau Galang. Laluan dirancang dengan kemas dan kami boleh berhenti bergambar di banyak tempat. Disyorkan untuk kumpulan.','published','2026-11-15 05:52:10','2026-11-15 05:59:29',NULL),(4,'Alyssa','uploads/testimonials/9206f88412c4d29900903d79984676aa.png',5,'Booking on WhatsApp got a fast reply and the price was explained up front. The trip was comfortable, there was only a bit of traffic on the way back in the evening.','Booking lewat WhatsApp cepat dibalas dan harga dijelaskan dari awal. Perjalanan nyaman, hanya sempat sedikit macet saat pulang sore.','Tempahan melalui WhatsApp dibalas dengan cepat dan harga diterangkan dari awal. Perjalanan selesa, cuma sedikit sesak ketika pulang pada waktu petang.','published','2026-11-15 05:52:10','2026-11-15 06:06:11',NULL),(5,'Amanda','uploads/testimonials/8fb696f2035e991eadafe18e616e61cb.png',5,'Great driver who knows Batam well. Picked us up at Harbour Bay and took us around the city. The car was clean and comfortable. Will book again.','Sopir hebat yang sangat mengenal Batam. Kami dijemput di Harbour Bay lalu diajak keliling kota. Mobil bersih dan nyaman. Pasti pesan lagi.','Pemandu yang hebat dan sangat mengenali Batam. Kami diambil di Harbour Bay dan dibawa bersiar-siar di sekitar bandar. Kereta bersih dan selesa. Pasti akan tempah lagi.','published','2026-11-15 05:52:10','2026-11-15 06:01:26',NULL),(6,'Afwan','uploads/testimonials/de308cc9727c1ae46a0fad1f3625f6a2.png',5,'We used the Alphard for a wedding. The car smelled fresh, and the driver was neatly dressed and on time. Our family guests were very happy.','Pakai Alphard untuk acara pernikahan. Mobil wangi, sopir berpakaian rapi dan tepat waktu. Tamu keluarga kami sangat puas.','Kami guna Alphard untuk majlis perkahwinan. Kereta wangi, pemandu berpakaian kemas dan tepat pada masanya. Tetamu keluarga kami sangat berpuas hati.','published','2026-11-15 05:52:10','2026-11-15 06:02:44',NULL),(7,'Dita','uploads/testimonials/efd60add4ddeaf9bb84feed5b2ff48b5.png',5,'Half-day city tour to Maha Vihara Duta Maitreya and a souvenir centre. The driver gave us many tips on where to eat. Just right for a short holiday.','City tour setengah hari ke Maha Vihara Duta Maitreya dan pusat oleh-oleh. Sopir memberi banyak rekomendasi tempat makan. Pas untuk liburan singkat.','Lawatan bandar separuh hari ke Maha Vihara Duta Maitreya dan pusat cenderamata. Pemandu memberi banyak cadangan tempat makan. Sesuai untuk percutian singkat.','published','2026-11-15 05:52:10','2026-11-15 11:48:54',NULL);

/*Table structure for table `migrations` */

DROP TABLE IF EXISTS `migrations`;

CREATE TABLE `migrations` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `version` varchar(255) NOT NULL,
  `class` varchar(255) NOT NULL,
  `group` varchar(255) NOT NULL,
  `namespace` varchar(255) NOT NULL,
  `time` int(11) NOT NULL,
  `batch` int(11) unsigned NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=15 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

/*Data for the table `migrations` */

insert  into `migrations`(`id`,`version`,`class`,`group`,`namespace`,`time`,`batch`) values (1,'2025-01-01-000001','App\\Database\\Migrations\\CreateCInformation','default','App',1794017803,1),(2,'2025-01-01-000002','App\\Database\\Migrations\\CreateCNews','default','App',1794017803,1),(3,'2025-01-01-000003','App\\Database\\Migrations\\CreateCFleet','default','App',1794017803,1),(4,'2025-01-01-000004','App\\Database\\Migrations\\CreateCFaqs','default','App',1794017803,1),(5,'2025-01-01-000005','App\\Database\\Migrations\\CreateCGallery','default','App',1794017803,1),(6,'2025-01-01-000006','App\\Database\\Migrations\\CreateSiteConfig','default','App',1794017803,1),(7,'2025-01-01-000007','App\\Database\\Migrations\\CreateAdminUsers','default','App',1794017803,1),(8,'2025-02-01-000001','App\\Database\\Migrations\\AddSeoColumnsToSiteConfig','default','App',1794051800,2),(9,'2025-02-01-000002','App\\Database\\Migrations\\CreateVisitorLogs','default','App',1794051994,3),(10,'2025-02-01-000003','App\\Database\\Migrations\\CreateSiteEvents','default','App',1794051994,3),(11,'2025-03-01-000001','App\\Database\\Migrations\\AddAboutToSiteConfig','default','App',1794674005,4),(12,'2025-03-02-000001','App\\Database\\Migrations\\AddImageToNews','default','App',1794677699,5),(13,'2025-03-03-000001','App\\Database\\Migrations\\CreateCTestimonials','default','App',1794696265,6),(14,'2025-03-04-000001','App\\Database\\Migrations\\AddLanguagesToTestimonialReview','default','App',1794696945,7);

/*Table structure for table `site_config` */

DROP TABLE IF EXISTS `site_config`;

CREATE TABLE `site_config` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `hero_title_en` varchar(255) DEFAULT NULL,
  `hero_title_id` varchar(255) DEFAULT NULL,
  `hero_title_ms` varchar(255) DEFAULT NULL,
  `hero_subtitle_en` varchar(500) DEFAULT NULL,
  `hero_subtitle_id` varchar(500) DEFAULT NULL,
  `hero_subtitle_ms` varchar(500) DEFAULT NULL,
  `about_body_en` text DEFAULT NULL,
  `about_body_id` text DEFAULT NULL,
  `about_body_ms` text DEFAULT NULL,
  `gallery_title_en` varchar(255) DEFAULT NULL,
  `gallery_title_id` varchar(255) DEFAULT NULL,
  `gallery_title_ms` varchar(255) DEFAULT NULL,
  `contact_body_en` text DEFAULT NULL,
  `contact_body_id` text DEFAULT NULL,
  `contact_body_ms` text DEFAULT NULL,
  `contact_email` varchar(255) DEFAULT NULL,
  `contact_address` varchar(500) DEFAULT NULL,
  `whatsapp_number` varchar(16) DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `site_name_en` varchar(150) DEFAULT NULL,
  `meta_description_en` varchar(320) DEFAULT NULL,
  `meta_keywords_en` varchar(255) DEFAULT NULL,
  `site_name_id` varchar(150) DEFAULT NULL,
  `meta_description_id` varchar(320) DEFAULT NULL,
  `meta_keywords_id` varchar(255) DEFAULT NULL,
  `site_name_ms` varchar(150) DEFAULT NULL,
  `meta_description_ms` varchar(320) DEFAULT NULL,
  `meta_keywords_ms` varchar(255) DEFAULT NULL,
  `og_image` varchar(500) DEFAULT NULL,
  `about_title_en` varchar(150) DEFAULT NULL,
  `about_title_id` varchar(150) DEFAULT NULL,
  `about_title_ms` varchar(150) DEFAULT NULL,
  `about_image` varchar(500) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

/*Data for the table `site_config` */

insert  into `site_config`(`id`,`hero_title_en`,`hero_title_id`,`hero_title_ms`,`hero_subtitle_en`,`hero_subtitle_id`,`hero_subtitle_ms`,`about_body_en`,`about_body_id`,`about_body_ms`,`gallery_title_en`,`gallery_title_id`,`gallery_title_ms`,`contact_body_en`,`contact_body_id`,`contact_body_ms`,`contact_email`,`contact_address`,`whatsapp_number`,`created_at`,`updated_at`,`site_name_en`,`meta_description_en`,`meta_keywords_en`,`site_name_id`,`meta_description_id`,`meta_keywords_id`,`site_name_ms`,`meta_description_ms`,`meta_keywords_ms`,`og_image`,`about_title_en`,`about_title_id`,`about_title_ms`,`about_image`) values (1,'Rent a Car for Your Next Journey','Sewa Mobil untuk Perjalanan Anda Berikutnya','Sewa Kereta untuk Perjalanan Anda Seterusnya','Comfortable, well-maintained vehicles with friendly drivers and flexible rental plans.','Kendaraan nyaman dan terawat dengan pengemudi ramah dan paket sewa fleksibel.','Kenderaan selesa dan terjaga dengan pemandu mesra serta pelan sewaan fleksibel.','Kimigo Travel is a travel transportation and vehicle rental service in Batam, here to accompany all kinds of journeys, from airport transfers and city tours to family holidays and group trips.\r\n\r\nOur fleet covers every need: comfortable MPVs for families, the premium Alphard for VIP guests, Hiace vans for groups, and medium buses for large parties. Every vehicle is regularly serviced and driven by friendly drivers.\r\n\r\nBooking is easy: choose your vehicle, chat with us on WhatsApp, and we will arrange the rest. Flexible rental plans fit your schedule, so you can focus on enjoying your holiday.','Kimigo Travel hadir sebagai layanan transportasi wisata dan rental kendaraan di Batam untuk menemani berbagai kebutuhan perjalanan Anda, mulai dari antar-jemput bandara dan city tour hingga liburan keluarga dan perjalanan rombongan.\r\n\r\nArmada kami beragam: MPV nyaman untuk keluarga, Alphard premium untuk tamu VIP, Hiace untuk rombongan, hingga bus medium untuk kelompok besar. Setiap kendaraan rutin diservis dan dikemudikan oleh sopir yang ramah.\r\n\r\nPemesanan mudah: pilih kendaraan, hubungi kami lewat WhatsApp, dan kami yang mengatur sisanya. Paket sewa yang fleksibel menyesuaikan jadwal Anda, sehingga Anda bisa fokus menikmati liburan.','Kimigo Travel ialah perkhidmatan pengangkutan pelancongan dan sewaan kenderaan di Batam untuk menemani pelbagai keperluan perjalanan anda, daripada pengangkutan lapangan terbang dan lawatan bandar hingga percutian keluarga dan perjalanan berkumpulan.\r\n\r\nArmada kami pelbagai: MPV selesa untuk keluarga, Alphard premium untuk tetamu VIP, van Hiace untuk kumpulan, hingga bas sederhana untuk rombongan besar. Setiap kenderaan diservis secara berkala dan dipandu oleh pemandu yang mesra.\r\n\r\nTempahan mudah: pilih kenderaan, hubungi kami melalui WhatsApp, dan kami uruskan selebihnya. Pelan sewaan yang fleksibel menyesuaikan jadual anda, supaya anda boleh menikmati percutian dengan tenang.','Our Gallery','Galeri Kami','Galeri Kami','Have a question or ready to book? Get in touch with us and we will reply as soon as possible.','Punya pertanyaan atau siap memesan? Hubungi kami dan kami akan membalas secepat mungkin.','Ada soalan atau sedia untuk menempah? Hubungi kami dan kami akan membalas secepat mungkin.','halokimigo@gmail.com','Tj. Uncang ruko Pluto blok A4 no 1 Batam, 29442','+6282381496827','2026-11-07 02:36:55','2026-11-15 12:59:17','Kimigo Travel','Rent a car or minibus with driver in Batam. Comfortable, well-maintained vehicles for airport transfers, city tours and group trips. Book via WhatsApp.','car rental Batam, Batam transport, minibus rental Batam, car with driver Batam, airport transfer Batam, Batam city tour, Batam travel, Kimigo Travel','Kimigo Travel','Sewa mobil dan minibus dengan sopir di Batam. Armada nyaman dan terawat untuk antar-jemput bandara, city tour, dan rombongan. Pesan via WhatsApp.','sewa mobil Batam, rental mobil Batam, sewa minibus Batam, sewa mobil dengan sopir Batam, antar jemput bandara Batam, city tour Batam, transportasi Batam, Kimigo Travel','Kimigo Travel','Sewa kereta dan minibas dengan pemandu di Batam. Kenderaan selesa untuk pengangkutan lapangan terbang, lawatan bandar dan rombongan. Tempah di WhatsApp.','sewa kereta Batam, sewa minibas Batam, kereta dengan pemandu Batam, pengangkutan lapangan terbang Batam, lawatan bandar Batam, pelancongan Batam, Kimigo Travel',NULL,'Comfortable Journeys, More Memorable Holidays','Perjalanan Nyaman, Liburan Lebih Berkesan','Perjalanan Selesa, Percutian Lebih Bermakna','uploads/about/ea2db398e62a66f15e8da403da75c390.png');

/*Table structure for table `site_events` */

DROP TABLE IF EXISTS `site_events`;

CREATE TABLE `site_events` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `event_type` varchar(50) NOT NULL,
  `ref_id` int(10) unsigned DEFAULT NULL,
  `ref_label` varchar(200) DEFAULT NULL,
  `lang` char(2) NOT NULL,
  `visitor_hash` char(64) NOT NULL,
  `created_at` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_site_events_type_created` (`event_type`,`created_at`),
  KEY `idx_site_events_ref` (`ref_id`)
) ENGINE=InnoDB AUTO_INCREMENT=841 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

/*Data for the table `site_events` */

